/// `ConfigOptions.lua:160-170` `conditionStationary`
fn a160_condition_stationary(v: &LV, c: &mut ApplyCtx<'_>) -> LuaResult<()> {
    let mut val: LV = v.clone();
    if leq(&ltype(&val), &ls("boolean")) {
        val = { let t = { let t = val.clone(); if truthy(Some(&t)) { ln(1.0) } else { t } }; if truthy(Some(&t)) { t } else { ln(0.0) } };
    }
    let l_sanitized_value: LV = lmax(&ln(0.0), &val, 165)?;
    nmod(c.mod_list, "Multiplier:StationarySeconds", ModType::Base, lval(&l_sanitized_value), Some("Config"), vec![]);
    if lt(&ln(0.0), &l_sanitized_value, 167)? {
        nmod(c.mod_list, "Condition:Stationary", ModType::Flag, Value::Bool(true), Some("Config"), vec![]);
    }
    Ok(())
}

