/// `ConfigOptions.lua:2073-2079` `maniaDebuffsCount`
fn a2073_mania_debuffs_count(v: &LV, c: &mut ApplyCtx<'_>) -> LuaResult<()> {
    let mut val: LV = v.clone();
    val = lmin(&val, &ln(15.0), 2074)?;
    nmod(c.enemy_mod_list, "DamageTaken", ModType::Inc, lval(&arith(Ar::Mul, &val, &ln(4.0), 2075, "local 'val'", "")?), Some(&lua_tostring(&concat(&val, &ls(" Mania Stacks"), 2075, "local 'val'", "")?)), vec![Tag::new(table(&[("type", s("GlobalEffect")), ("effectType", s("Debuff"))])), cond("AfflictedByMania")]);
    nmod(c.enemy_mod_list, "ActionSpeed", ModType::Inc, lval(&arith(Ar::Mul, &unm(&val, 2076, "local 'val'")?, &ln(2.0), 2076, "", "")?), Some(&lua_tostring(&concat(&val, &ls(" Mania Stacks"), 2076, "local 'val'", "")?)), vec![Tag::new(table(&[("type", s("GlobalEffect")), ("effectType", s("Debuff"))])), cond("AfflictedByMania")]);
    nmod(c.enemy_mod_list, "LifeRecoveryRate", ModType::Inc, lval(&arith(Ar::Mul, &unm(&val, 2077, "local 'val'")?, &ln(10.0), 2077, "", "")?), Some(&lua_tostring(&concat(&val, &ls(" Mania Stacks"), 2077, "local 'val'", "")?)), vec![Tag::new(table(&[("type", s("GlobalEffect")), ("effectType", s("Debuff"))])), cond("AfflictedByMania")]);
    nmod(c.enemy_mod_list, "EnergyShieldRecoveryRate", ModType::Inc, lval(&arith(Ar::Mul, &unm(&val, 2078, "local 'val'")?, &ln(10.0), 2078, "", "")?), Some(&lua_tostring(&concat(&val, &ls(" Mania Stacks"), 2078, "local 'val'", "")?)), vec![Tag::new(table(&[("type", s("GlobalEffect")), ("effectType", s("Debuff"))])), cond("AfflictedByMania")]);
    Ok(())
}

