/// `ConfigOptions.lua:2223-2244` `deliriousPercentage`
fn a2223_delirious_percentage(v: &LV, c: &mut ApplyCtx<'_>) -> LuaResult<()> {
    if leq(v, &ls("20Percent")) {
        nmod(c.enemy_mod_list, "DamageTaken", ModType::More, Value::Num(-16.0), Some("20% Delirious"), vec![]);
        nmod(c.enemy_mod_list, "Damage", ModType::Inc, Value::Num(6.0), Some("20% Delirious"), vec![]);
    }
    if leq(v, &ls("40Percent")) {
        nmod(c.enemy_mod_list, "DamageTaken", ModType::More, Value::Num(-32.0), Some("40% Delirious"), vec![]);
        nmod(c.enemy_mod_list, "Damage", ModType::Inc, Value::Num(12.0), Some("40% Delirious"), vec![]);
    }
    if leq(v, &ls("60Percent")) {
        nmod(c.enemy_mod_list, "DamageTaken", ModType::More, Value::Num(-48.0), Some("60% Delirious"), vec![]);
        nmod(c.enemy_mod_list, "Damage", ModType::Inc, Value::Num(18.0), Some("60% Delirious"), vec![]);
    }
    if leq(v, &ls("80Percent")) {
        nmod(c.enemy_mod_list, "DamageTaken", ModType::More, Value::Num(-64.0), Some("80% Delirious"), vec![]);
        nmod(c.enemy_mod_list, "Damage", ModType::Inc, Value::Num(24.0), Some("80% Delirious"), vec![]);
    }
    if leq(v, &ls("100Percent")) {
        nmod(c.enemy_mod_list, "DamageTaken", ModType::More, Value::Num(-80.0), Some("100% Delirious"), vec![]);
        nmod(c.enemy_mod_list, "Damage", ModType::Inc, Value::Num(30.0), Some("100% Delirious"), vec![]);
    }
    Ok(())
}

